def words(text):
    try:
        return shlex.split(text, comments=True)
    except ValueError:
        return text.split()

def norm(text):
    return text.lower().replace('_', '-').replace('.', '-')

def boolean(text):
    return str(text).lower() in ('1', 'true', 'yes', 'on')

COLUMN_DEFAULTS = {
 'line-number': {'display':'yes','interval':'5'},
 'id': {'display':'yes','color':'no'},
 'date': {'display':'default','use-author':'no','local':'no','format':'%Y-%m-%d'},
 'author': {'display':'full'}, 'committer': {'display':'full'},
 'file-name': {'display':'auto'}, 'file-size': {'display':'default'},
 'mode': {'display':'yes'}, 'ref': {'display':'yes'},
 'status': {'display':'short'},
 'commit-title': {'display':'yes','graph':'no','refs':'no'}, 'text': {}
}
ENUMS = {
 'commit-order': ['auto','default','topo','date','author-date','reverse'],
 'line-graphics': ['default','utf-8','ascii','auto'],
 'ignore-space': ['no','all','some','at-eol'],
 'ignore-case': ['no','yes','smart-case'],
 'vertical-split': ['auto','no','yes'],
