}
COL_ENUMS = {
 'date':['default','relative','relative-compact','custom','no'],
 'author':['full','abbreviated','email','email-user','no'],
 'committer':['full','abbreviated','email','email-user','no'],
 'file-name':['auto','always','no'], 'file-size':['default','units','no'],
 'status':['short','long','no'],
}

