            with open(os.path.join(os.path.dirname(__file__), 'defaults.conf'),'rb') as f:
                self.template=f.read()
        self.template=self.template.decode()
        self.values = OrderedDict()
        self.columns = {}
        self.bindings = OrderedDict()
        self.binding_groups = {}
        self.colors = OrderedDict()
        self.color_lines = []
        self.messages = []
        self.custom_bindings = set()
        group=''
        for line in self.template.splitlines():
            if line.startswith('# '): group=line[2:]
            w=words(line)
            if not w: continue
            if w[0]=='set':
                self.values[w[1]] = ' '.join(w[3:])
                if w[1].endswith('-view'): self.parse_columns(w[1],w[3:])
            elif w[0]=='bind':
                k=(w[1],self.key(w[2]))
                # Preserve quoted command arguments in bindings.
                action=re.split(r'\s+',line.strip(),3)[3]
                self.bindings[k] = action
                self.binding_groups[k] = group
            elif w[0]=='color':
                self.colors[w[1]] = w[2:]
                self.color_lines.append(line)
        self.defaults=self.values.copy()
        self.extra = {'file-args':'','rev-args':''}

    @staticmethod
    def key(k):
        aliases={'lt':'LessThan','lessthan':'LessThan','hash':'Hash', 'space':'Space',
          'enter':'Enter','return':'Enter','tab':'Tab','backspace':'Backspace','esc':'Escape','escape':'Escape',
          'pgup':'PageUp','pageup':'PageUp','pgdown':'PageDown','pagedown':'PageDown',
          'ins':'Insert','insert':'Insert','del':'Delete','delete':'Delete',
          'backtab':'ShiftTab','shifttab':'ShiftTab','singlequote':'SingleQuote','doublequote':'DoubleQuote'}
