        except (ValueError,TypeError): return default

    def parse_columns(self,k,parts):
        cols=OrderedDict()
        for spec in parts:
            name,sep,opts=spec.partition(':')
            name=norm(name)
            if name not in COLUMN_DEFAULTS: continue
            d=OrderedDict(COLUMN_DEFAULTS[name])
            if opts:
                for i,x in enumerate(opts.split(',')):
                    xname,equal,val=x.partition('=')
                    if equal: d[norm(xname)]=val
                    elif i==0:
                        d['display']=self.column_value(name,x)
                    else: d[norm(xname)]='yes'
