                view=v; key=key[len(p):]; break
        if key.startswith('show-'): key=key[5:]
        if key.endswith('-display'): key=key[:-8]
        for name in sorted(COLUMN_DEFAULTS,key=len,reverse=True):
            if key==name: return view,name,'display'
            if key.startswith(name+'-'): return view,name,key[len(name)+1:]
        return None

    def set(self,key,args,current='main'):
        key=norm(key)
        if isinstance(args,str): args=words(args)
        if key.endswith('-view') and key[:-5] in VIEWS:
            self.parse_columns(key,args); self.values[key]=' '.join(args); return None
        cs=self.col_setting(key,current)
        if cs and (key not in self.values or '-view-' in key):
            v,c,opt=cs
            if c not in self.columns.get(v,{}): return "No '%s' column in the %s view"%(c,v)
            val=' '.join(args)
            # A column shortcut may include multiple suboptions, just like a column spec.
            if opt=='display' and ',' in val:
                items=val.split(','); val=items.pop(0)
                for item in items:
                    n,_,x=item.partition('='); self.columns[v][c][n]=x or 'yes'
            if opt=='display': val=self.column_value(c,val)
            if opt in ('graph',) and val not in ('no','v1','v2'): val='v2' if boolean(val) else 'no'
            self.columns[v][c][opt]=val
            return None
        if key in ('file-args','rev-args'):
            self.extra[key]=' '.join(args); return None
        if key not in self.values: return 'Unknown option name: '+key
        val=' '.join(args)
        if key in ENUMS:
            if val not in ENUMS[key]:
                if key=='line-graphics': val='default' if boolean(val) else 'ascii'
                elif key=='ignore-space': val='all' if boolean(val) else 'no'
                elif key=='ignore-case': val='yes' if boolean(val) else 'no'
                elif key=='vertical-split': val='yes' if boolean(val) else 'no'
                else:
                    default=self.defaults.get(key,ENUMS[key][0]); self.values[key]=default
                    return "'%s' is not a valid value for %s; using %s"%(val,key,default)
        elif self.defaults.get(key) in ('yes','no') and key not in ('show-notes','diff-highlight'):
            val='yes' if boolean(val) else 'no'
        ranges={'tab-size':(1,1024),'diff-context':(0,999999),'id-width':(0,40), 'history-size':(0,999999),'mouse-scroll':(1,999999)}
        if key in ranges:
            lo,hi=ranges[key]
            try: n=int(val)
            except ValueError: n=0
            if not lo<=n<=hi: return 'Value must be between %d and %d'%(lo,hi)
            val=str(n)
        self.values[key]=val
        return None

    def toggle(self,key,args,current):
        key=norm(key)
        cs=self.col_setting(key,current)
