            v,c,opt=cs
            if c not in self.columns.get(v,{}): return "No '%s' column in the %s view"%(c,v)
            d=self.columns[v][c]
            old=d.get(opt,'no')
            if opt=='display': vals=COL_ENUMS.get(c,['yes','no'])
            elif opt=='graph': vals=['v2','v1','no']
            else: vals=['yes','no']
            if args:
                try: val=str(int(old)+int(args[0]))
                except ValueError: val=args[0]
            else: val=vals[(vals.index(old)+1)%len(vals)] if old in vals else vals[0]
            d[opt]=val
            return None
        if key not in self.values: return 'Unknown option name: '+key
        old=self.values[key]
        if args:
            arg=args[0]
            if arg.startswith(('+','-')) and arg.strip('+-').rstrip('%').isdigit() and old.rstrip('%').isdigit():
                val=str(max(0,int(old.rstrip('%'))+int(arg.rstrip('%'))))+('%' if '%' in old else '')
