    def load(self,path,current='main',depth=0,explicit=False):
        path=os.path.expanduser(os.path.expandvars(path))
        if not path: return
        try:
            with open(path,encoding='utf-8',errors='replace') as f: lines=f.read().splitlines()
        except OSError as e:
            if explicit: self.messages.append('tig warning: %s: %s'%(path,e.strerror))
            return
        joined=''; errors=False
        for i,line in enumerate(lines,1):
            if line.endswith('\\'):
                joined+=line[:-1]+' '; continue
            joined+=line
            error=self.command(joined,current,path,depth); joined=''
