        if errors: self.messages.append('tig warning: Errors while loading %s.'%path)

    def serialize_columns(self,v):
        result=[]
        for c,d in self.columns.get(v,{}).items():
            items=[]
            if c=='text':
                items=[k+'='+x for k,x in d.items() if k!='display']
            else:
                # Unadorned columns have their natural defaults implicit.
                show=d.get('display','yes')
                if c in ('mode','ref','file-size') and show==COLUMN_DEFAULTS[c].get('display'):
                    pass
                else: items.append(show)
                for k,x in d.items():
                    if k=='display': continue
                    if k=='format': x='"'+x.replace('"','\\"')+'"'
                    items.append(k+'='+x)
            result.append(c+(':'+','.join(items) if items else ''))
        return ' '.join(result)

    def save(self,path):
        out=[]
        for line in self.template.splitlines():
            w=words(line)
            if w and w[0]=='set':
                k=w[1]; val=self.values[k]
                if k.endswith('-view'): val=self.serialize_columns(k[:-5])
                elif k in ('diff-highlight','truncation-delimiter'): val='"'+val+'"'
                out.append('set %-25s = %s'%(k,val))
            elif w and w[0]=='bind':
                k=(w[1],self.key(w[2]))
                if k in self.bindings:
                    out.append('bind %-10s %-15s %s'%(w[1],w[2],self.bindings[k]))
            elif w and w[0]=='color':
                if self.colors.get(w[1])==w[2:]: out.append(line)
                else:
                    name=w[1]; name='"'+name+'"' if ' ' in name else name
                    cols=self.colors.get(w[1],w[2:]); out.append('color %-30s %-8s %-8s %s'%(name,cols[0],cols[1],' '.join(cols[2:])))
            else: out.append(line)
        # Additional user bindings are kept when exporting options.
        for k in self.custom_bindings:
            if not any(words(x)[1:3]==[k[0],k[1]] for x in self.template.splitlines() if x.startswith('bind ')):
                out.append('bind %-10s %-15s %s'%(k[0],k[1],self.bindings[k]))
        with open(path,'w') as f: f.write('\n'.join(out)+'\n')
