        return rows

    def reflog(self,stash=False,args=None):
        cmd=['stash','list'] if stash else ['reflog','show']
        self.trace(['git']+cmd+['--encoding=UTF-8','--no-color','--pretty=raw']+list(args or []))
        out=self.git(cmd+['--date=raw','--format=%H%x00%gD%x00%gs']+list(args or []))
        records=[]
        for line in out.splitlines():
            p=line.split('\0')
            if len(p)<3: continue
            r=dict(self.commit(p[0])); r.update(reflog=p[1],subject=p[2],type='main-commit')
