"""View records, column layout, and screen-independent rendering."""
import datetime
import math
import re
import time
import unicodedata
from settings import boolean

PLAIN={'diff','log','stage','blob','pager'}


def width(s):
    return sum(0 if unicodedata.combining(c) else 2 if unicodedata.east_asian_width(c) in ('W','F') else 1 for c in s)

def cut(s,n):
    out=[]; size=0
    for c in s:
        w=0 if unicodedata.combining(c) else 2 if unicodedata.east_asian_width(c) in ('W','F') else 1
        if size+w>n: break
        out.append(c); size+=w
    return ''.join(out)

def pad(s,n,right=False):
    s=cut(s,n)
    return (' '*max(0,n-width(s))+s) if right else (s+' '*max(0,n-width(s)))

def fit(s,n,delimiter='~'):
    if n<1: return ''
    if width(s)>n: return cut(s,max(0,n-width(delimiter)))+delimiter
    return pad(s,n)


def line_record(text,plain=False):
    typ='default'; cells=[text]
    if not plain:
        rules=[('commit ','commit'),('Refs: ','pp-refs'),('diff --','diff-header'),
          ('--- ','diff-del-file'),('+++ ','diff-add-file'),('@@','diff-chunk'),
          ('new file mode ','diff-newfmode'),('deleted file mode ','diff-delfmode'),
          ('old mode ','diff-oldmode'),('new mode ','diff-newmode'),('index ','diff-index'),
          ('similarity index ','diff-similarity'),('Binary files ','diff-bin'),
          ('+','diff-add'),('-','diff-del')]
        for p,t in rules:
            if text.startswith(p): typ=t; break
        if text=='---': typ='diff-start'
        if any(text.startswith(p) for p in ('Author: ','AuthorDate: ','Commit: ','CommitDate: ','Date: ','Tagger: ','Merge: ','TaggerDate: ','tree ','parent ','author ','committer ','copy from ','copy to ','rename from ','rename to ','dissimilarity ','diff-tree ','    Signed-off-by:','    Acked-by:','    Reviewed-by:')): typ=''
        if typ=='diff-chunk':
            m=re.match(r'(@@@?.*?@@@?)(.*)',text)
            if m: cells=list(m.groups())
        elif re.match(r'^ .+ \| ',text):
            typ='diff-stat'
            a,b=text.split('|',1)
            m=re.match(r'(.*?)(\+*)(-*)$',b)
            cells=[a,'|'+m[1]]+[x for x in (m[2],m[3]) if x]
    r={'type':typ,'text':text,'cells':cells}
    m=re.match(r'commit ([0-9a-f]{40,64})',text)
    if m: r['oid']=m[1]
    return r

