 ('View-specific actions',[('status-update','Stage/unstage chunk or file changes'),('status-revert','Revert chunk or file changes'),('status-merge','Merge file using external tool'),('stage-update-line','Stage/unstage single line'),('stage-update-part','Stage/unstage part of a chunk'),('stage-split-chunk','Split current diff chunk')]),
