 ('Misc',[('edit','Open in editor'),('prompt','Open the prompt'),('options','Open the options menu'),('screen-redraw','Redraw the screen'),('stop-loading','Stop all loading views'),('show-version','Show version information'),('none','Do nothing')])])
ACTIONS={k:d for group in ACTION_INFO.values() for k,d in group}
