class FatalError(Exception): pass

class App:
    def __init__(self,start='main',args=None,startline=0,stdin_data=None):
        self.start=start; self.args=list(args or []); self.startline=startline
        self.input_data=stdin_data
        self.settings=Settings()
        self.repo=Repository(self.settings)
        self.gitconfig=dict(self.repo.gitconfig)
        self.load_settings()
        self.renderer=Renderer(self)
        self.current=None; self.views={}; self.display=[]; self.history=[]
        self.message=''; self.running=True; self.window=None; self.no_display=bool(os.environ.get('TIG_NO_DISPLAY'))
        self.screen_h=24; self.screen_w=80
        if self.no_display:
            try: self.screen_h=int(os.environ.get('LINES',24)); self.screen_w=int(os.environ.get('COLUMNS',80))
            except ValueError: pass
        self.pending_prompt=None; self.prompt_text=''; self.option_menu=False
        self.confirm=None; self.script_stack=[]
        self.active_commit=self.repo.head or 'HEAD'; self.active_file=''; self.active_blob=''
        self.head_arg='HEAD'; self.active_directory=''; self.script_mode='TIG_SCRIPT' in os.environ
        self.expanded_help={'generic','search','toggle'}
        self.last_search=''; self.search_backward=False
        self.colors={}; self.color_pairs={}

    def load_settings(self):
        sysrc=os.environ.get('TIGRC_SYSTEM')
        if sysrc is not None: self.settings.load(sysrc,explicit=bool(sysrc))
        else: self.settings.load('/etc/tigrc')
        user=os.environ.get('TIGRC_USER')
        if user is None:
            xdg=os.environ.get('XDG_CONFIG_HOME')
            if xdg: user=os.path.join(xdg,'tig','config')
            else:
                user=os.path.expanduser('~/.config/tig/config')
                if not os.path.exists(user): user=os.path.expanduser('~/.tigrc')
        self.settings.load(user)
        if os.environ.get('TIG_DIFF_OPTS') and not self.settings.get('diff-options'):
            self.settings.set('diff-options',words(os.environ['TIG_DIFF_OPTS']))
        for k,v in self.repo.gitconfig:
            if k.startswith('tig.'):
                key=k[4:]
                if key.startswith('bind.'):
                    w=words(v)
                    if len(w)>1: self.settings.bind(key[5:],w[0],v.split(None,1)[1])
                elif key.startswith('color.'):
                    self.settings.colors[key[6:]]=words(v)
                else:
                    err=self.settings.set(key,words(v))
                    if err: self.settings.messages.append('tig warning: '+err)
            elif k=='status.showuntrackedfiles':
                if v=='no': self.settings.values['status-show-untracked-files']='no'
                elif v=='normal': self.settings.values['status-show-untracked-dirs']='no'
            elif k=='diff.noprefix': self.settings.values['diff-noprefix']='yes' if boolean(v) else 'no'

    def initialize(self):
        if self.start!='pager' and not self.repo.exists: raise FatalError('Not a git repository')
        v=View(self.start,self.args)
        if self.start=='blame':
            self.prepare_blame(v,self.args)
        elif self.start=='pager': v.context['input']=self.input_data or ''
        self.load(v,initial=True)
        self.current=v; self.display=[v]; self.views[v.name]=v
        self.layout()
        if self.startline: v.move(self.startline,True)
        self.update_state()

    def prepare_blame(self,v,args):
        args=list(args); opts=[]; rest=[]; i=0; separator=False
        while i<len(args):
            a=args[i]; i+=1
            if a=='--': separator=True; continue
            if a.startswith('-') and not separator:
                opts.append(a)
                if a in ('-L','--contents') and i<len(args): opts.append(args[i]); i+=1
            else: rest.append(a)
        if not rest: raise FatalError('Invalid number of options to blame\n\n'+self.help_text().rstrip())
        rev=None; file=None
        if len(rest)>1:
            candidate=self.repo.git(['rev-parse','--verify',rest[0]],False).strip()
            if re.fullmatch('[0-9a-f]{40,64}',candidate): rev=rest[0]; file=rest[1]
            elif os.path.exists(os.path.join(self.repo.cwd,rest[0])):
                raise FatalError('Invalid number of options to blame\n\n'+self.help_text().rstrip())
            else: file=rest[0]
        else: file=rest[0]
        if self.repo.prefix and not os.path.isabs(file): file=self.repo.prefix+file
        if os.path.isabs(file): file=os.path.relpath(file,self.repo.root)
        v.context.update(file=file,oid=rev,blameopts=opts)
        self.active_file=file

    def load(self,v,initial=False):
        name=v.name; r=self.repo; s=self.settings
        v.rows=[]
        if name=='main':
            commits,rc=r.main(v.args)
            if not commits:
                if initial: raise FatalError('No revisions match the given arguments.')
                self.message='No revisions match the given arguments.'
            rows=[]
            if s.yes('show-changes') and any(c['oid']==r.head for c in commits):
                dirty=r.dirty(trace=True)
                for group in ('untracked','unstaged','staged'):
                    if group=='untracked' and not s.yes('show-untracked'): continue
                    if dirty[group]:
                        who={'name':'Not Committed Yet','email':'','time':int(time.time()),'zone':datetime.datetime.now().astimezone().strftime('%z')}
                        rows.append({'type':'stat-'+group,'oid':'0'*40,'parents':['0'*40],'subject':group.capitalize()+' changes','author':who,'committer':who,'group':group})
            v.rows=rows+commits
            self.compute_graph(v)
            if s.yes('start-on-head'):
                v.pos=next((i for i,x in enumerate(v.rows) if x.get('oid')==r.head),0)
        elif name=='log': self.load_text(v,r.log(v.args),refs=True)
        elif name=='diff':
            if v.context.get('group'):
                group=v.context['group']; out=r.stage(group,[])
                v.context['fixed_ref']=group.capitalize()+' changes'
            else: out=r.show(v.context.get('oid'),v.args)
            self.load_text(v,out,refs=True,describe=True)
            v.base_ref=v.context.get('oid') or next((x['oid'] for x in v.rows if x.get('oid')),'HEAD')
        elif name=='refs':
            r.trace(['git','log','--encoding=UTF-8','--no-color','--date=raw','--pretty=format:%H%x00%aN <%aE> %ad%x00%cN <%cE> %cd%x00%s','--all','--decorate-refs=','--simplify-by-decoration'])
            refs=r.ref_list[:]
            if '--branches' in v.args: refs=[x for x in refs if x['kind'] in ('head','branch')]
            if '--tags' in v.args: refs=[x for x in refs if x['kind'] in ('tag','local-tag')]
            if '--remotes' in v.args: refs=[x for x in refs if x['kind'] in ('remote','tracked-remote')]
            for ref in refs:
                item=dict(r.commit(ref['oid'])); item.update(ref); item['type']='default'; v.rows.append(item)
            v.rows.sort(key=lambda x:(-x.get('committer',{}).get('time',0),x['kind']!='head',x['name']))
            v.rows.insert(0,{'allrefs':True,'name':'All references','type':'default'})
        elif name=='tree':
            oid=v.context.get('oid') or self.active_commit or 'HEAD'; directory=v.context.get('directory','')
            if oid=='0'*40: oid='HEAD'
            v.context.update(oid=oid,directory=directory)
            v.rows=[{'type':'header','header':True,'text':'Directory path /'+directory}]
            if directory: v.rows.append({'type':'directory','parentdir':True,'filename':'..','mode':'040000','kind':'tree'})
            v.rows+=r.tree(oid,directory)
            if not v.loaded: v.pos=1 if len(v.rows)>1 else 0
        elif name=='blob':
            file=v.context.get('file',self.active_file); oid=v.context.get('oid')
            v.context['file']=file; v.ref=file
            self.load_text(v,r.blob(file,oid),plain=True)
            if v.context.get('line'): v.pos=max(0,v.context['line']-1)
        elif name=='blame':
            file=v.context.get('file') or self.active_file
            if not file: self.message='No file chosen'; return
            v.rows,rc=r.blame(file,v.context.get('oid'),v.context.get('blameopts'))
            if rc or not v.rows:
                if initial: raise FatalError('No blame exist for '+file)
                self.message='No blame exist for '+file
        elif name=='status':
            r.trace(['git','update-index','-q','--unmerged','--refresh'])
            if r.head: r.trace(['git','diff-index','-z','--diff-filter=ACDMRTXB','-C','--cached','HEAD','--'])
            r.trace(['git','diff-files','-z']); r.trace(['git','ls-files','-z','--others','--exclude-standard'])
            dirty=r.dirty(all_files=True)
            head='On branch '+r.branch if r.branch else 'HEAD detached at '+r.head[:7]
            if not r.head: head='Initial commit'
            v.rows=[{'type':'header','header':True,'text':head}]
            only=v.context.get('group')
            for group,title in [('staged','Changes to be committed:'),('unstaged','Changes not staged for commit:'),('untracked','Untracked files:')]:
                if only and only!=group: continue
                v.rows.append({'type':'stat-'+group,'section':True,'group':group,'text':title})
                if dirty[group]:
                    for item in dirty[group]: v.rows.append(dict(item,type='stat-'+group,group=group))
                else: v.rows.append({'type':'stat-none','none':True,'group':group,'text':'  (no files)'})
        elif name=='stage':
            group=v.context.get('group','unstaged'); file=v.context.get('file','')
            if group=='untracked': self.load_text(v,r.blob(file),plain=True)
            else: self.load_text(v,r.stage(group,[file,v.context.get('old',file)] if file else []))
        elif name=='grep':
            raw=r.grep(v.args) if v.args else []
            grouping=s.col('grep','file-name').get('display','no')=='no'
            last=None
            for row in raw:
                if grouping and row['file']!=last:
                    v.rows.append({'type':'file','header':True,'file':row['file'],'lineno':0})
                last=row['file']; v.rows.append(row)
        elif name in ('stash','reflog'): v.rows=r.reflog(name=='stash',v.args)
        elif name=='pager': self.load_text(v,v.context.get('input',''),refs=True)
        elif name=='help': self.load_help(v)
        v.loaded=True; v.clamp()
        self.renderer.update_ref(v)

    def load_text(self,v,text,refs=False,describe=False,plain=False):
        # split on newlines, not arbitrary Unicode separators in source files.
        lines=text.split('\n')
        if lines and not lines[-1]: lines.pop()
        for line in lines:
            if line.endswith('\r'): line=line[:-1]
            row=line_record(line,plain); v.rows.append(row)
            if refs and row.get('oid'):
                dec=self.repo.decorations(row['oid'],', ')
                if describe:
                    desc=self.repo.describe(row['oid'])
                    if desc and not any(x['name']==desc for x in self.repo.refs.get(row['oid'],[])):
                        dec+=(', ' if dec else '')+desc
                if dec: v.rows.append(line_record('Refs: '+dec))

    def compute_graph(self,v):
        # Lane assignment is independent of terminal rendering.  Each commit
        # replaces its current lane with the first parent and adds merge lanes.
        lanes=[]
        for row in v.rows:
            if row.get('type','').startswith('stat-'): continue
            oid=row.get('oid',''); parents=row.get('parents',[])
            if oid not in lanes: lanes.append(oid)
            idx=lanes.index(oid); chars=[]
            for j in range(len(lanes)):
                chars.append('* ' if j==idx else '| ')
            if len(parents)>1: chars.extend(['- ']*(len(parents)-1))
            row['graph']=''.join(chars)
            lanes.pop(idx)
            for parent in reversed(parents):
                if parent not in lanes: lanes.insert(idx,parent)

    def load_help(self,v):
        rows=[{'type':'header','text':'Quick reference for tig keybindings:'}, {'type':'section','text':'[-] Collapse all sections','help_section':'all'}, {'type':'default','text':''}]
        all_maps=[]
        for mapname,key in self.settings.bindings:
            if mapname not in all_maps: all_maps.append(mapname)
        for mapname in all_maps+['toggle']:
            expanded=mapname in self.expanded_help
            rows.append({'type':'section','text':('[-]' if expanded else '[+]')+' '+mapname+' bindings','help_section':mapname})
            if not expanded: continue
            if mapname=='toggle':
                rows.append({'type':'help-group','text':'Toggle keys (enter: o <key>):'})
                for k,a,d in TOGGLES: rows.append({'type':'default','text':pad(k,28,True)+' '+pad(a,26)+' '+d})
                continue
            groups=OrderedDict()
            for (mp,key),action in self.settings.bindings.items():
                if mp!=mapname: continue
                if action.startswith(':toggle '): group='Option toggling:'
                elif action.startswith(':'): group='Internal commands:'
                elif norm(action) not in ACTIONS: group='External commands:'
                else: group=next((g for g,acts in ACTION_INFO.items() if any(a==norm(action) for a,d in acts)),'Misc')
                groups.setdefault(group,OrderedDict()).setdefault(action,[]).append(key)
            for group,acts in groups.items():
                rows.append({'type':'help-group','text':group})
                for action,keys in acts.items():
                    def showkey(k):
                        if k=='<LessThan>': return '<'
                        if k=='<Hash>': return '#'
                        if k==',': return "','"
                        return k
                    kt=', '.join(map(showkey,keys))
                    text=pad(kt,28,True)+' '+pad(action,26)
                    if norm(action) in ACTIONS: text+=' '+ACTIONS[norm(action)]
                    rows.append({'type':'default','text':text.rstrip(),'help_action':action})
        v.rows=rows

    def layout(self):
        h=max(3,self.screen_h)-1; w=max(8,self.screen_w)
        if len(self.display)==1:
            v=self.display[0]; v.x=v.y=0; v.width=w; v.height=max(1,h-1)
        elif len(self.display)>1:
            a,b=self.display[-2:]
            split=self.settings.get('vertical-split')
            vertical=split=='yes' or (split=='auto' and w>=160)
            if vertical:
                n=self.measure(self.settings.get('split-view-width'),w,50)
                n=max(4,min(n,w-4))
                a.x=0; b.x=w-n+1; a.y=b.y=0; a.width=w-n; b.width=n-1; a.height=b.height=h-1
            else:
                n=self.measure(self.settings.get('split-view-height'),h,67)
                n=max(4,min(n,h-4))
                a.x=b.x=0; a.y=0; b.y=h-n; a.width=b.width=w; a.height=h-n-1; b.height=n-1
        for v in self.display:
            if v.pos<v.offset: v.offset=v.pos
            if v.pos>=v.offset+v.height: v.offset=max(0,v.pos-v.height+1)

    def measure(self,value,total,default):
        try:
            return int(total*int(value[:-1])/100) if value.endswith('%') else int(value)
        except ValueError: return total*default//100

    def update_state(self):
        if not self.current: return
        v=self.current; row=v.selected()
        self.renderer.update_ref(v)
        oid=row.get('oid')
        if not oid and v.name in ('diff','log','pager'):
            oid=next((x.get('oid') for x in reversed(v.rows[:v.pos+1]) if x.get('oid')),None)
        if oid: self.active_commit=oid
        if row.get('file'): self.active_file=row['file']
        elif v.context.get('file'): self.active_file=v.context['file']
        if row.get('blob'): self.active_blob=row['blob']
        if v.name=='tree': self.active_directory=v.context.get('directory','')
        # Determine the selected filename and source line in a textual diff.
        if v.name in ('diff','stage'):
            file=''; new=old=0
            for x in v.rows[:v.pos+1]:
                text=x.get('text','')
                m=re.match(r'diff --git a/(.*?) b/(.*)',text)
                if m: file=m[2]
                m=re.match(r'@@ -([0-9]+)(?:,[0-9]+)? \+([0-9]+)(?:,[0-9]+)? @@',text)
                if m: old=int(m[1]); new=int(m[2]); continue
                if x.get('type')=='diff-add': new+=1
                elif x.get('type')=='diff-del': old+=1
                elif text.startswith(' '): old+=1; new+=1
            if file: self.active_file=file
            v.context['lineno']=max(0,new-1); v.context['lineno_old']=max(0,old-1)

    def open_view(self,name,context=None,args=None,split=False,reuse=False):
        old=self.current
        if name=='blame' and not (context or {}).get('file') and not self.active_file:
            self.message='No file chosen'; return
        if name=='blob' and not (context or {}).get('file') and not self.active_file:
            self.message='No file chosen'; return
        if name=='stage' and not context:
            self.message='The stage view is only available from the status view'; return
        if name=='grep' and args is None:
            self.pending_prompt='grep'; self.prompt_text=''; return
        if name=='pager' and context is None:
            if name not in self.views:
                self.message='No pager content'; return
            reuse=True
        if reuse and name in self.views: v=self.views[name]
        else:
            v=View(name,args)
            v.context.update(context or {})
            if name=='tree': v.context.setdefault('oid',self.active_commit); v.context.setdefault('directory','')
            if name in ('blob','blame'): v.context.setdefault('file',self.active_file)
            self.load(v)
        if old and old is not v:
            self.history.append((old,list(self.display)))
            v.prev=old
        if split and old:
            parent=old
            v.parent=parent
            self.display=[parent,v]
            self.current=v if self.settings.yes('focus-child') else parent
        else:
            self.display=[v]; self.current=v
            if not reuse: v.parent=None
        self.views[name]=v
        self.layout(); self.update_state()

    def close_view(self,quit_if_last=True):
        if len(self.display)>1:
            a,b=self.display[-2:]
            v=a if self.current is b else b
            self.current=v; self.display=[v]
            if self.history: self.history.pop()
        elif self.history:
            self.current,self.display=self.history.pop()
        elif quit_if_last: self.running=False
        self.layout(); self.update_state()

    def enter(self):
        v=self.current; row=v.selected(); name=v.name
        if name in ('main','stash','reflog'):
            group=row.get('group')
            if group=='untracked': self.open_view('status',{'group':'untracked'},split=True)
            elif group: self.open_view('diff',{'group':group},split=True)
            elif row.get('oid'): self.open_view('diff',{'oid':row['oid']},split=True)
        elif name=='refs':
            args=['--all'] if row.get('allrefs') else [row.get('full',row.get('name','HEAD'))]
            self.open_view('main',args=args,split=True)
        elif name=='tree':
            if row.get('header'): return
            if row.get('parentdir'): self.parent(); return
            if row.get('kind')=='tree':
                v.context['directory']=row['file']+'/'
                v.pos=1; v.offset=0; self.load(v)
            else: self.open_view('blob',{'file':row.get('file'),'oid':v.context['oid']},split=True)
        elif name=='status':
            if not row.get('group') or row.get('none'): return
            self.open_view('stage',{'group':row['group'],'file':row.get('file',''),'old':row.get('old','')},split=True)
        elif name=='grep': self.open_view('blob',{'file':row.get('file',''),'line':row.get('lineno',1)},split=True)
        elif name=='blame':
            if row.get('oid')=='0'*40: self.open_view('diff',{'group':'unstaged'},split=True)
            else:
                oid=row.get('oid'); file=row.get('source_file',self.active_file)
                self.open_view('diff',{'oid':oid,'fixed_ref':"Changes to '%s'"%file},args=['--',file],split=True)
                dv=self.views.get('diff')
                if dv:
                    # Jump to the blamed line in the selected file's patch.
                    target=next((i for i,x in enumerate(dv.rows) if x.get('type')=='diff-header'),0)
                    dv.offset=target
                    dv.pos=len(dv.rows)-1
        elif name=='log' or name=='pager' and row.get('oid'):
            oid=row.get('oid') or self.active_commit
            self.open_view('diff',{'oid':oid},split=True)
        elif name in ('diff','stage'):
            if row.get('type')=='diff-stat':
                file=row.get('text','').split('|',1)[0].strip()
                target=next((i for i,x in enumerate(v.rows) if x.get('type')=='diff-header' and file in x.get('text','')),None)
                if target is not None:
                    v.pos=target; v.offset=target
            else:
                v.offset=min(max(0,len(v.rows)-1),v.offset+1)
                if v.pos<v.offset: v.pos=v.offset
        elif name=='help':
            section=row.get('help_section')
            if section=='all':
                if self.expanded_help: self.expanded_help=set()
                else: self.expanded_help={m for m,k in self.settings.bindings}|{'toggle'}
            elif section:
                if section in self.expanded_help: self.expanded_help.remove(section)
                else: self.expanded_help.add(section)
            if section: self.load_help(v); v.clamp()
        self.update_state()

    def parent(self):
        v=self.current
        if v.name=='tree':
            d=v.context.get('directory','')
            if d:
                v.context['directory']='/'.join(d.rstrip('/').split('/')[:-1])
                if v.context['directory']: v.context['directory']+='/'
                v.pos=1; v.offset=0; self.load(v)
            else: self.message='Already in the root directory'
        elif v.name=='blame':
            r=v.selected(); oid=r.get('oid')
            p=self.repo.commit(oid).get('parents',[])
            if p: v.context['oid']=p[0]; self.load(v)
            else: self.message='The selected commit has no parents'
        else:
            oid=self.active_commit; p=self.repo.commit(oid).get('parents',[])
            if p:
                if v.name=='main': self.goto(p[0])
                else: self.open_view('diff',{'oid':p[0]})
            else: self.message='The selected commit has no parents'

    def refresh(self):
        self.repo.load_refs()
        self.repo.head=self.repo.git(['rev-parse','--verify','HEAD']).strip()
        self.repo.branch=self.repo.git(['symbolic-ref','--quiet','--short','HEAD']).strip()
        for v in self.display: self.load(v)
        self.layout(); self.update_state()

    def action(self,action):
        act=norm(action); v=self.current
        if not v: return
        if act.startswith('view-') and act[5:] in VIEWS:
            name=act[5:]
            if name==v.name:
                self.display=[v]; self.layout(); return
            if name=='help': self.expanded_help.add(v.name)
            context=None; args=None
            if name=='diff': context={'oid':self.active_commit} if self.active_commit!='0'*40 else {'group':v.selected().get('group','unstaged')}
            if name=='blame': context={'file':self.active_file,'oid':v.context.get('oid') if v.name in ('tree','blob') else None}
            if name=='log': args=self.args if self.start=='main' else []
            self.open_view(name,context,args,reuse=name in self.views and name in ('main','help','status','log','refs','stash','pager'))
            return
        if act in ('quit',): self.running=False
        elif act in ('view-close','view-close-no-quit'): self.close_view(act=='view-close')
        elif act=='enter': self.enter()
        elif act=='back': self.close_view(False)
        elif act=='parent': self.parent()
        elif act=='maximize': self.display=[v]; self.layout()
        elif act=='view-next':
            if len(self.display)>1: self.current=self.display[(self.display.index(v)+1)%len(self.display)]; self.update_state()
            else: self.message='Only one view is displayed'
        elif act=='refresh': self.refresh()
        elif act in ('next','previous'):
            d=1 if act=='next' else -1
            if len(self.display)>1 and v is self.display[-1] and v.parent:
                p=v.parent; p.move(p.pos+d); self.current=p; self.update_state()
                self.enter()
            else: v.move(v.pos+d)
        elif act.startswith('move-'):
            dest=v.pos
            if act=='move-down': dest+=1
            elif act=='move-up': dest-=1
            elif act=='move-page-down': dest+=v.height
            elif act=='move-page-up': dest-=v.height
            elif act=='move-half-page-down': dest+=v.height//2
            elif act=='move-half-page-up': dest-=v.height//2
            elif act=='move-first-line': dest=0
            elif act=='move-last-line': dest=len(v.rows)-1
            elif act in ('move-next-merge','move-prev-merge'):
                step=1 if act=='move-next-merge' else -1
                dest=next((i for i in range(v.pos+step,len(v.rows) if step==1 else -1,step) if len(v.rows[i].get('parents',[]))>1),v.pos)
            v.move(dest)
        elif act.startswith('scroll-'):
            if act in ('scroll-left','scroll-right'):
                n=self.measure(self.settings.get('horizontal-scroll'),v.width,50)
                v.col=max(0,v.col+max(1,n)*(1 if act.endswith('right') else -1))
            elif act=='scroll-first-col': v.col=0
            else:
                n=v.height if 'page' in act else 1
                if 'half' in act: n=v.height//2
                if act.endswith('up'): n=-n
                v.offset=max(0,min(max(0,len(v.rows)-1),v.offset+n))
                v.pos=max(v.offset,min(v.pos,v.offset+v.height-1))
        elif act in ('search','search-back','prompt'):
            self.pending_prompt={'search':'/','search-back':'?','prompt':':'}[act]; self.prompt_text=''
        elif act in ('find-next','find-prev'): self.search(None,act=='find-prev')
        elif act=='options': self.option_menu=True
        elif act=='show-version': self.message='tig version 2.6.0-g6d1ab9a'
        elif act in ('status-update','stage-update-line','stage-update-part'): self.stage_update(act)
        elif act=='status-revert': self.revert()
        elif act=='edit': self.edit()
        elif act=='none' or act in ('screen-redraw','stop-loading','stage-split-chunk'): pass
        else: self.message='Unknown action: '+action
        self.update_state()

    def search(self,pattern=None,backward=False):
        v=self.current
        if pattern is not None: self.last_search=pattern; v.search=pattern; self.search_backward=backward
        pattern=v.search or self.last_search
        if not pattern: self.message='No previous search'; return
        try:
            ignore=self.settings.get('ignore-case')
            rex=re.compile(pattern,re.I if ignore=='yes' or ignore=='smart-case' and pattern.lower()==pattern else 0)
        except re.error as e: self.message='Invalid search pattern: '+str(e); return
        sizes=self.renderer.column_widths(v)
        d=-1 if backward else 1
        candidates=list(range(v.pos+d,len(v.rows) if d==1 else -1,d))
        if self.settings.yes('wrap-search'): candidates+=list(range(0 if d==1 else len(v.rows)-1,v.pos+d,d))
        for i in candidates:
            text=''.join(x for x,c in self.renderer.segments(v,v.rows[i],i,sizes))
            if rex.search(text):
                v.move(i,True); self.message="Line %d matches '%s'"%(i+1,pattern); return
        self.message="No match found for '%s'"%pattern

    def goto(self,rev):
        v=self.current
        oid=self.repo.git(['rev-parse','--verify',rev]).strip()
        target=next((i for i,x in enumerate(v.rows) if x.get('oid','').startswith(rev) or x.get('oid')==oid),None)
        if target is not None: v.move(target,True)
        else: self.message="Unable to find commit '%s'"%rev

    def substitute(self,text):
        row=self.current.selected(); v=self.current
        branch=row.get('name',self.repo.branch) if v.name=='refs' else self.repo.branch
        data={'head':self.head_arg,'commit':self.active_commit,'blob':self.active_blob,'file':self.active_file,'file_old':row.get('old',self.active_file),
          'branch':branch,'refname':row.get('name',''),'tag':row.get('name','') if row.get('kind') in ('tag','local-tag') else '',
          'stash':row.get('reflog',''),'directory':self.active_directory or '.', 'ref':v.context.get('oid') or 'HEAD',
          'lineno':str(row.get('lineno',v.context.get('lineno',v.pos+1 if v.name=='blob' else 0))), 'lineno_old':str(row.get('orig_lineno',v.context.get('lineno_old',0))),
          'text':row.get('text',row.get('subject','')),'repo:head':self.repo.branch,'repo:head-id':self.repo.head,'repo:cdup':self.repo.cdup,'repo:prefix':self.repo.prefix,
          'repo:git-dir':self.repo.gitdir,'repo:worktree':self.gitconfig.get('core.worktree',''), 'repo:is-inside-work-tree':'false' if self.repo.bare else 'true',
          'remote':branch.split('/')[0] if row.get('kind')=='remote' else '',
          'repo:remote':self.gitconfig.get('branch.'+self.repo.branch+'.remote',''),'repo:upstream':'','revargs':' '.join(self.args),'fileargs':'','cmdlineargs':''}
        for t in ('diff','blame','log','main'): data[t+'args']=self.settings.get(t+'-options')
        return re.sub(r'%\(([^)]+)\)',lambda m:data.get(m[1],''),text)

    def command(self,text):
        text=text.strip()
        if text.startswith(':'): text=text[1:]
        if not text: return
        w=words(text)
        if not w: return
        cmd=norm(w[0]); v=self.current
        self.message=''
        if text.isdigit(): v.move(int(text)-1,True)
        elif text.startswith(('/', '?')): self.search(text[1:],text[0]=='?')
        elif text.startswith('!'):
            args=words(self.substitute(text[1:]))
            out,_=self.repo.run(args)
            self.open_view('pager',{'input':out})
        elif cmd in ('set','bind','color','source'):
            err=self.settings.command(text,v.name)
            if err: self.message=err
            if cmd=='set':
                key=norm(w[1]) if len(w)>1 else ''
                if any(key.startswith(x) for x in ('diff-options','diff-context','ignore-space','word-diff','show-changes','main-options','commit-order','status-show','grep-view')):
                    self.load(v)
            if cmd=='color': self.init_colors()
            self.layout()
        elif cmd=='toggle':
            if len(w)<2: self.message='No option name given'; return
            key=norm(w[1])
            if key in ('sort-order','sort-field'):
                if key=='sort-order': v.sort_reverse=not v.sort_reverse
                if v.name in ('refs','tree'): v.rows[1:]=list(reversed(v.rows[1:]))
                elif v.name not in ('main','log','diff','blame'): v.rows.reverse()
            else:
                err=self.settings.toggle(w[1],w[2:],v.name)
                if err: self.message=err
                if key in ('ignore-space','diff-context','diff-options','word-diff','commit-order','show-changes','show-untracked','status-show-untracked-dirs','status-show-untracked-files') or key.startswith('grep-view'):
                    self.load(v)
            self.layout()
        elif cmd=='goto' and len(w)>1: self.goto(self.substitute(w[1]))
        elif cmd=='save-display':
            if len(w)>1: self.save_display(os.path.expanduser(self.substitute(w[1])))
        elif cmd=='save-view':
            if len(w)>1: self.renderer.save_view(v,os.path.expanduser(self.substitute(w[1])))
        elif cmd=='save-options':
            if len(w)>1: self.settings.save(os.path.expanduser(self.substitute(w[1])))
        elif cmd=='script' and len(w)>1: self.run_script(os.path.expanduser(w[1]))
        elif cmd=='echo': self.message=self.substitute(' '.join(w[1:]))
        elif cmd=='exec': self.external(text[len(w[0]):].strip())
        elif cmd in ACTIONS: self.action(cmd)
        elif cmd in VIEWS or cmd=='show':
            target='diff' if cmd=='show' else cmd
            if target=='blame':
                nv=View('blame',w[1:]); self.prepare_blame(nv,w[1:]); self.open_view('blame',nv.context,w[1:])
            else: self.open_view(target,args=w[1:])
        elif len(w[0])==1 and len(w)==1: self.key(w[0])
        elif re.fullmatch('[0-9a-fA-F]{4,64}',text): self.goto(text)
        else: self.message="Unknown command '%s'"%w[0]
        self.update_state()

    def key(self,key):
        key=self.settings.key(key)
        if self.option_menu:
            self.option_menu=False
            target=next((o for k,o,d in TOGGLES if self.settings.key(k)==key),None)
            if target: self.command('toggle '+target)
            return
        if self.confirm:
            callback=self.confirm; self.confirm=None
            if key.lower()=='y': callback()
            self.message=''; return
        if key=='<Ctrl-C>': self.running=False; return
        if self.pending_prompt is not None:
            if key in ('<Enter>','\n','\r'):
                kind=self.pending_prompt; text=self.prompt_text; self.pending_prompt=None; self.prompt_text=''
                if kind==':': self.command(text)
                elif kind=='grep': self.open_view('grep',args=words(text))
                else: self.search(text,kind=='?')
            elif key=='<Escape>': self.pending_prompt=None; self.prompt_text=''; self.message=''
            elif key in ('<Backspace>','<Ctrl-H>'): self.prompt_text=self.prompt_text[:-1]
            elif key=='<Ctrl-U>': self.prompt_text=''
            elif len(key)==1: self.prompt_text+=key
            elif key=='<Space>': self.prompt_text+=' '
            return
        self.message=''
        action=self.settings.bindings.get((self.current.name,key),self.settings.bindings.get(('generic',key)))
        if action:
            if action.startswith(':'): self.command(action[1:])
            elif norm(action) in ACTIONS: self.action(action)
            else: self.external(action)
        else: self.message="Unknown key, press 'h' for help"

    def run_script(self,path=None,data=None):
        if data is None:
            try:
                with open(path,encoding='utf-8',errors='replace') as f: data=f.read()
            except OSError as e: raise FatalError('Failed to open script: '+str(e))
        for line in data.splitlines():
            if not self.running: break
            if line.startswith('#') and len(line)>1: continue
            if not line: continue
            if line.startswith(':'):
                self.command(line[1:])
            elif line.startswith('/') or line.startswith('?'):
                self.search(line[1:],line.startswith('?'))
            else:
                tokens=re.findall(r'<[^>]+>|.',line)
                for token in tokens:
                    if not self.running: break
                    self.key(token)
            self.layout(); self.update_state()
            if self.window: self.draw()

    def stage_update(self,kind='status-update'):
        v=self.current; row=v.selected(); group=row.get('group') if v.name=='status' else v.context.get('group')
        if v.name not in ('status','stage') or not group: self.message='Nothing to update'; return
        file=row.get('file','') if v.name=='status' else v.context.get('file','')
        if v.name=='stage' and group in ('staged','unstaged') and (row.get('type')=='diff-chunk' or kind in ('stage-update-line','stage-update-part')):
            ok=self.apply_chunk(v,group,kind)
            if ok:
                for w in self.display: self.load(w)
                return
        files=[file] if file else [x['file'] for x in self.repo.dirty(all_files=True)[group]]
        if not files: self.message='Nothing to update'; return
        if group=='staged':
            cmd=['reset','-q','HEAD','--']+files if self.repo.head else ['rm','--cached','-q','--']+files
        else: cmd=['add','--']+files
        out,rc=self.repo.run(['git']+cmd,cwd=self.repo.root)
        self.message=out.strip() if rc else ''
        if v.name=='stage': self.close_view(False)
        for view in self.display: self.load(view)
        self.layout()

    def apply_chunk(self,v,group,kind):
        # Extract the current file header and hunk, adjusting line counts for
        # single-line staging.  git apply performs all index validation.
        pos=v.pos; lines=[r.get('text','') for r in v.rows]
        hs=next((i for i in range(pos,-1,-1) if lines[i].startswith('@@')),None)
        fs=next((i for i in range(pos,-1,-1) if lines[i].startswith('diff --')),None)
        if hs is None or fs is None: return False
        end=next((i for i in range(hs+1,len(lines)) if lines[i].startswith(('@@','diff --'))),len(lines))
        header=lines[fs:hs]; hunk=lines[hs:end]
        if kind in ('stage-update-line','stage-update-part'):
            body=[]
            for i,line in enumerate(hunk[1:],hs+1):
                if i==pos or not line.startswith(('+','-')): body.append(line)
                elif group=='unstaged':
                    if line.startswith('-'): body.append(' '+line[1:])
                else:
                    if line.startswith('+'): body.append(' '+line[1:])
            m=re.match(r'@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@(.*)',hunk[0])
            if m:
                old=sum(not x.startswith('+') for x in body); new=sum(not x.startswith('-') for x in body)
                hunk=['@@ -%s,%d +%s,%d @@%s'%(m[1],old,m[2],new,m[3])]+body
        patch='\n'.join(header+hunk)+'\n'
        cmd=['git','apply','--cached','--recount']+(['--reverse'] if group=='staged' else [])
        out,rc=self.repo.run(cmd,data=patch,cwd=self.repo.root)
        if rc: self.message=out.strip()
        return not rc

    def revert(self):
        v=self.current; row=v.selected()
        file=row.get('file') or v.context.get('file')
        if not file: self.message='Nothing to revert'; return
        def callback():
            self.repo.git(['checkout','--',file],root=True)
            for w in self.display: self.load(w)
        self.message="Revert changes to '%s'? [Yy/Nn]"%file; self.confirm=callback

    def external(self,command):
        command=self.substitute(command); flags=''
        while command and command[0] in '!?@<+>': flags+=command[0]; command=command[1:]
        if not command: return
        def run():
            args=words(command)
            if not args: return
            if '!' in flags and self.window:
                curses.def_prog_mode(); curses.endwin()
                subprocess.run(args,cwd=self.repo.cwd)
                curses.reset_prog_mode()
            else:
                out,rc=self.repo.run(args)
                if '+' in flags: self.message=out.splitlines()[0] if out else ''
            if '<' in flags: self.running=False
            else:
                for v in self.display: self.load(v)
        if '?' in flags:
            self.message='Run '+command+'? [Yy/Nn]'; self.confirm=run
        else: run()

    def edit(self):
        file=self.active_file
        if not file: self.message='No file chosen'; return
        editor=os.environ.get('TIG_EDITOR') or os.environ.get('GIT_EDITOR') or self.gitconfig.get('core.editor') or os.environ.get('VISUAL') or os.environ.get('EDITOR') or 'vi'
        line=self.current.selected().get('lineno',self.current.pos+1)
        command=editor+' '+('+'+str(line)+' ' if self.settings.yes('editor-line-number') else '')+shlex.quote(file)
        self.external('!sh -c '+shlex.quote(command))

    def save_display(self,path):
        self.layout()
        grid=[[' ']*self.screen_w for _ in range(self.screen_h-1)]
        for v in self.display:
            rows=self.renderer.lines(v)
            for j,segs in enumerate(rows):
                text=''.join(x for x,c in segs)
                y=v.y+j
                if y>=len(grid): break
                # Saving preserves printable Unicode; only wide-character
                # continuation cells are omitted from the textual export.
                x=v.x
                for ch in text:
                    if x>=v.x+v.width or x>=self.screen_w: break
                    grid[y][x]=ch
                    wc=width(ch)
                    for k in range(1,wc):
                        if x+k<self.screen_w: grid[y][x+k]=''
                    x+=wc
            y=v.y+v.height
            if y<len(grid):
                for j,ch in enumerate(self.renderer.title(v)):
                    if v.x+j<self.screen_w: grid[y][v.x+j]=ch
        if len(self.display)>1 and self.display[1].x:
            x=self.display[1].x-1
            for line in grid: line[x]='|'
        with open(path,'w') as f:
            for line in grid: f.write((''.join(line).rstrip() or ' ')+'\n')

    def init_colors(self):
        if not self.window: return
        try:
            curses.start_color(); curses.use_default_colors()
        except curses.error: pass
        self.colors={}; self.color_pairs={}
        color_names={'default':-1,'black':0,'red':1,'green':2,'yellow':3,'blue':4,'magenta':5,'cyan':6,'white':7}
        no_color=bool(os.environ.get('NO_COLOR'))
        for area,parts in self.settings.colors.items():
            if len(parts)<2: continue
            fg=color_names.get(parts[0],-1); bg=color_names.get(parts[1],-1)
            for i,p in enumerate(parts[:2]):
                if p.startswith('color') and p[5:].isdigit():
                    if i==0: fg=int(p[5:])
                    else: bg=int(p[5:])
            key=(fg,bg); attr=0
            if not no_color:
                if key not in self.color_pairs:
                    num=len(self.color_pairs)+1
                    try: curses.init_pair(num,fg,bg); self.color_pairs[key]=num
                    except curses.error: self.color_pairs[key]=0
                attr=curses.color_pair(self.color_pairs[key])
            attrs={'bold':curses.A_BOLD,'dim':curses.A_DIM,'underline':curses.A_UNDERLINE,'reverse':curses.A_REVERSE,'blink':curses.A_BLINK}
            for a in parts[2:]: attr|=attrs.get(a,0)
            self.colors[area]=attr
        # Column colors use the prefix rules associated with the same fields.
        self.colors.setdefault('author',self.colors.get('author ',0))
        self.colors.setdefault('committer',self.colors.get('committer ',0))
        self.colors.setdefault('commit-title',self.colors.get('default',0))
        self.colors.setdefault('text',self.colors.get('default',0))
        self.colors.setdefault('file-name',self.colors.get('file',0))

    def color(self,v,style,text=''):
        c=self.colors
        if style=='':
            for prefix in sorted(c,key=len,reverse=True):
                if prefix.endswith((' ',':')) and text.startswith(prefix): return c[prefix]
            return c.get('default',0)
        return c.get(v.name+'.'+style,c.get(style,c.get('default',0)))

    def draw(self):
        if not self.window: return
        w=self.window
        self.screen_h,self.screen_w=w.getmaxyx(); self.layout()
        try: w.erase()
        except curses.error: pass
        for v in self.display:
            rows=self.renderer.lines(v)
            for j,segs in enumerate(rows):
                y=v.y+j; x=v.x; selected=v.offset+j==v.pos and v.pos<len(v.rows)
                ca=self.colors.get('cursor' if self.current is v else 'cursor-blur',curses.A_REVERSE)
                if selected:
                    try: w.addstr(y,x,' '*v.width,ca)
                    except curses.error: pass
                for text,style in segs:
                    attr=ca if selected else self.color(v,style,text)
                    if style=='commit-title' and not selected:
                        self.draw_title_segments(w,v,y,x,text,attr)
                    else:
                        try: w.addstr(y,x,text,attr)
                        except (curses.error,ValueError): pass
                    x+=width(text)
            title=self.renderer.title(v)
            try: w.addstr(v.y+v.height,v.x,cut(title,v.width),self.colors.get('title-focus' if self.current is v else 'title-blur',curses.A_REVERSE))
            except curses.error: pass
        if len(self.display)>1 and self.display[1].x:
            x=self.display[1].x-1
            for y in range(self.screen_h-1):
                try: w.addstr(y,x,'|',self.colors.get('title-blur',0))
                except curses.error: pass
        msg=self.message
        if self.pending_prompt is not None:
            prefix='grep: ' if self.pending_prompt=='grep' else self.pending_prompt
            msg=prefix+self.prompt_text
        try: w.addstr(self.screen_h-1,0,cut(msg,max(0,self.screen_w-1)),self.colors.get('status',0))
        except curses.error: pass
        if self.option_menu: self.draw_menu()
        try:
            if self.pending_prompt is not None:
                curses.curs_set(1); w.move(self.screen_h-1,min(self.screen_w-1,width(msg)))
            else: curses.curs_set(0)
            w.refresh()
        except curses.error: pass

    def draw_title_segments(self,w,v,y,x,text,default):
        # Commit graph and ref labels have independent colors from the subject.
        row=v.rows[v.offset+(y-v.y)]
        graph=self.renderer.graph(v,0,row)
        if graph and text.startswith(graph):
            try: w.addstr(y,x,graph,self.colors.get('graph-commit',default))
            except curses.error: pass
